define({"topics":[{"title":"Installing host system software","shortdesc":"<p class=\"shortdesc\">This quick start guide provides an overview of the procedures required to load host system software. Refer to the tasks included within this procedure for detailed information.<\/p>","href":"r_InstallingHostSystemSoftware.html","attributes":{"data-id":"id_2003115"},"menu":{"hasChildren":true},"tocID":"id_2003115-d46e31342","next":"id_2003115-d46e31342"},{"title":"Security levels ","shortdesc":"<p class=\"shortdesc\">To access HIPAA\/Security Levels, launch Guided Install from the Service Desktop Manager and select the HIPAA\/Security tab.<\/p>","href":"c_Security-Levels_16504382_2.html","attributes":{"data-id":"id_15271117"},"menu":{"hasChildren":false},"tocID":"id_15271117-d46e32824","topics":[]},{"title":"Service licensing ","shortdesc":"<p class=\"shortdesc\">Secure Service Access (SSA) is a secure service key platform for GE medical devices developed to improve the service license renewal and replacement processes. <\/p>","href":"c_ServiceLicenseOverview_2.html","attributes":{"data-id":"id_2000507"},"menu":{"hasChildren":true},"tocID":"id_2000507-d46e32930","next":"id_2000507-d46e32930"},{"title":"Installing service packs","shortdesc":"<p class=\"shortdesc\">When GE releases new software versions, it may be necessary to install updates to a host PC. <\/p>","href":"t_InstallingServicePacks.html","attributes":{"data-id":"id_2002881"},"menu":{"hasChildren":true},"tocID":"id_2002881-d46e33351","next":"id_2002881-d46e33351"},{"title":"System and hardware configuration","shortdesc":"<p class=\"shortdesc\">This topic describes the values and explanation of each parameter for system configuration and hardware configuration in Guided Install.<\/p>","href":"r_SystemAndHardwareConfiguration.html","attributes":{"data-id":"id_2003307"},"menu":{"hasChildren":true},"tocID":"id_2003307-d46e34190","next":"id_2003307-d46e34190"},{"title":"Installing operator documentation (online help)","shortdesc":"<p class=\"shortdesc\"> Load the operator manuals onto the host computer so customers can have access to the manuals any time they are using the system.<\/p>","href":"t_InstallingOperatorDocumentation.html","attributes":{"data-id":"id_2001527"},"menu":{"hasChildren":false},"tocID":"id_2001527-d46e34400","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_13.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e34506","topics":[]}]});